import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"堆与优先队列","description":"","frontmatter":{"title":"堆与优先队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-priority.md","filePath":"cs/heap-priority.md","lastUpdated":1789023840000}'),c={name:"cs/heap-priority.md"};function m(_,a,T,f,u,A){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="堆与优先队列" tabindex="-1">堆与优先队列 <a class="header-anchor" href="#堆与优先队列" aria-label="Permalink to &quot;堆与优先队列&quot;">​</a></h1><div class="epigraph"><p>只要反复取出当前最小，不必维持全部键的中序；完全二叉树里父小于子女，数组下标就能当指针。</p><footer>—— 据 Williams, Algorithm 232: Heapsort, CACM 1964；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/bplus-as-ds">上一课</a>和<a href="/cs/rbtree-intuition">红黑树直觉</a>把有序字典做到对数。优先队列的合同更窄：insert 与 extract-min（或 max），不要 successor、不要中序遍历。<a href="/cs/array-random-access">数组与随机访问</a>已经给出下标算术。<a href="/cs/amortized-analysis">摊还分析</a>不是本课必需——二叉堆单次最坏已是 \\(\\Theta(\\log n)\\)。本课不重讲 B 树分裂。缺口是堆：完全树 + 堆序，用数组表示。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用 BST 当优先队列可以，但维护全序浪费。无序数组 extract-min 要扫 \\(\\Theta(n)\\)。缺口是部分序：<strong>父键 \\(\\le\\) 子女键</strong>（最小堆），根即当前最小；形状是完全二叉树，从而高度 \\(\\lfloor\\log_2 n\\rfloor\\)，且能塞进数组：\\(i\\) 的子女 \\(2i,2i+1\\)。</p><p>insert：放末尾上滤。extract-min：用末尾填根再下滤。均为 \\(\\Theta(\\log n)\\)。建堆可以自底向上 \\(\\Theta(n)\\)，后课堆排序会用。</p><p><span class="marginnote">Williams 1964 的堆排序把这套结构送进排序课。本课只交 ADT。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽象：优先队列。表示：数组 \\(A[1..n]\\)（或从 0 偏置）。堆不变式加形状不变式。上滤/下滤交换父与子，直到序恢复。</p>',9)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E6%95%B0%E7%BB%84%E5%AE%8C%E5%85%A8%E6%A0%91%22%5D%20--%3E%20ROOT%5B%22A%5B1%5D%20%E6%9C%80%E5%B0%8F%22%5D%0A%20%20ROOT%20--%3E%20L%5B%22A%5B2%5D%22%5D%0A%20%20ROOT%20--%3E%20R%5B%22A%5B3%5D%22%5D%0A%20%20L%20--%3E%20L2%5B%22A%5B4%5D%20A%5B5%5D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>decrease-key 在 Dijkstra 里需要：沿父走 \\(\\Theta(\\log n)\\)。若没有到数组下标的句柄，找元素会退回 \\(\\Theta(n)\\)。合同要声明是否提供句柄。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>堆不支持高效查找任意键，不是字典。与 BST 分工：要序遍历用树；只要最小用堆。二项堆、斐波那契堆把 decrease-key 摊还做得更低，算法课需要时再请；主干先二叉堆。</p><p>数组表示吃空间局部性：下滤走的地址仍有一定跳跃（\\(2i\\)），比链表好，比顺序扫差。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把堆排序证完，不引入 \\(d\\) 叉堆的调参。也不把操作系统的进程就绪队列写成必须用堆——那是调度课的选择。</p><p>后课默认：优先队列 = 堆合同，\\(\\Theta(\\log n)\\) 插入与取端。按任意键 \\(O(1)\\) 期望查找是散列的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>优先队列不需要全序；堆序 + 完全形状足够。</li><li>数组下标当父子，insert/extract-min 为 \\(\\Theta(\\log n)\\)。</li><li>无序键的期望 \\(O(1)\\) 查找靠下一课散列函数。</li><li>出处：Williams, <em>CACM</em>, 1964；Cormen et al. 第 6 章。</li></ul>',9))])}const D=o(c,[["render",m]]);export{x as __pageData,D as default};
